import { EntityCard } from '@refy-design/web';
import type { ComponentProps } from 'react';
const photos = {
  homeQuiet: 'https://refy.design/demo/ape-silencioso.webp',
  shopTeapot: 'https://refy.design/demo/loja-bule.webp',
  personClara: 'https://refy.design/demo/pessoa-clara.webp',
};
export function Example() {
  const args: Pick<
    ComponentProps<typeof EntityCard>,
    | 'title'
    | 'subtitle'
    | 'image'
    | 'imageAlt'
    | 'price'
    | 'meta'
    | 'badge'
    | 'badgeTone'
    | 'rating'
    | 'actions'
  > = {
    title: 'Cast iron teapot',
    subtitle: 'Kitchen · 1.2 liters',
    image: photos.shopTeapot,
    imageAlt: 'Black teapot on a wooden table',
    price: '$ 89',
    meta: 'Ships in 2 days',
    badge: 'New',
    badgeTone: 'info',
    rating: { value: 4.7, count: 212 },
    actions: [{ label: 'Add to cart' }, { label: 'Details' }],
  };
  return <EntityCard {...args} />;
}

